package dev.shadw.khemet.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Cobra with its own model and texture. Generated by shadw-mod mob. */
public class CobraRenderer extends MobRenderer<Cobra, CobraModel.State, CobraModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("khemet", "textures/entity/cobra.png");

	public CobraRenderer(EntityRendererProvider.Context context) {
		super(context, new CobraModel(context.bakeLayer(CobraModel.LAYER)), 0.6F);
	}

	@Override
	public CobraModel.State createRenderState() {
		return new CobraModel.State();
	}

	@Override
	public void extractRenderState(Cobra entity, CobraModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(CobraModel.State state) {
		return TEXTURE;
	}
}
